	 bool LRU, size_t N_L1_SETS, size_t N_L1_WAYS, bool SWAP_TAG_SET,
	 size_t LATENCY, storage_impl_type L2_STORAGE_IMPL = AUTO,
	 storage_impl_type L1_STORAGE_IMPL = AUTO>
