				m_tag[addr.m_addr_line] = addr.m_tag;
				m_valid[addr.m_addr_line] = true;
				m_dirty[addr.m_addr_line] = false;

				m_replacer.notify_insertion(addr);

				if (read) {
					// store loaded line to cache
					if (RAW_CACHE) {
						m_raw_cache_core.set_line(
								m_cache_mem,
								addr.m_addr_line,
