		string& operator=(const string& rhs)
		{
			if (this == &rhs) {
				return *this;
			}

			if (str_ != NULL) {
				delete[] str_;
				str_ = NULL;
				size_ = 0;
			}

			if (rhs.size_ == 0 || rhs.str_ == NULL) {
				str_ = NULL;
				size_ = 0;
			}
			else {
				str_ = new char[rhs.size_ + 1];
				size_ = rhs.size_;

				if (str_ != NULL) {
					memcpy(str_, rhs.str_, (size_ + 1) * sizeof(char));
				}
				else {
					size_ = 0;
				}
