		const size_t<3>& region,
		const VECTOR_CLASS<Event>* events = NULL,
		Event* event = NULL)
	{
		cl_int error;
		CommandQueue queue = CommandQueue::getDefault(&error);

		if (error != CL_SUCCESS) {
			return error;
		}

		return queue.enqueueCopyBufferToImage(
			src,
			dst,
			src_offset,
			dst_origin,
			region,
			events,
			event);
	}


	inline cl_int flush(void)
	{
		cl_int error;
		CommandQueue queue = CommandQueue::getDefault(&error);

		if (error != CL_SUCCESS) {
			return error;
		}

		return queue.flush();
	}

	inline cl_int finish(void)
	{
		cl_int error;
		CommandQueue queue = CommandQueue::getDefault(&error);

		if (error != CL_SUCCESS) {
			return error;
		}


		return queue.finish();
	}

