  // by far the most amount of time is spent inside this little function
  // inputs to this function are both quantized

  // wq - quantized weight matrix
  // ws - scaling factor for each row of wq
  // xq - quantized input vector
  // xs - scaling factor for xq
  // xout - output vector

  static int8_t x_buffer[N];
#pragma HLS ARRAY_RESHAPE variable=x_buffer type=block factor=2 dim=1
  static float xs_buffer[N / GS];
#pragma HLS ARRAY_RESHAPE variable=xs_buffer type=block factor=2 dim=1

x_buff:
  for (int i = 0; i < N; i++)
  {
#pragma HLS PIPELINE off
#pragma HLS UNROLL factor=1
    x_buffer[i] = xq[i];
  }
xs_buff:
  for (int j = 0; j <= N - GS; j += GS)
  {
#pragma HLS PIPELINE off
#pragma HLS UNROLL factor=1
    xs_buffer[j / GS] = xs[j / GS];
  }

  // Iterate over each row of the weight matrix
  for (int i = 0; i < D; i++)
  {
#pragma HLS PIPELINE off
#pragma HLS UNROLL factor=1
    float val = 0.0f;
    const int w_row_offset = i * N;
    const int ws_row_offset = i * (N / GS);

    // do the matmul in groups of GS
    for (int j = 0; j <= N - GS; j += GS)
    {
#pragma HLS PIPELINE off
#pragma HLS UNROLL factor=1
      int32_t ival = 0;
      for (int k = 0; k < GS; k++)
      {
#pragma HLS PIPELINE off
#pragma HLS UNROLL factor=1
        int32_t buffer1 = (int32_t)x_buffer[j + k];
        // Read directly from the weight matrix in global memory
        int32_t buffer2 = (int32_t)wq[w_row_offset + j + k];
        if (buffer1 == -1) ival -= buffer2;
        if (buffer1 == 1) ival += buffer2;
