    LLVM_DEBUG(dbgs() << "Input xlnnames: " << names << '\n');
    LLVM_DEBUG(dbgs() << "Parsed name list:\n");
    LLVM_DEBUG(interleaveComma(ParamNames, dbgs()));

    renameBasicBlocksAndValues(M, ParamNames);
    return false;
  }
};

